declarations.code:
template <class... Args>

using format_string =

    basic_format_string<char, std::type_identity_t<Args>...>;

template <class... Args>

using wformat_string =

    basic_format_string<wchar_t, std::type_identity_t<Args>...>;

sections.text:
The alias templates format_string and wformat_string use std::type_identity_t to inhibit template argument deduction. Typically, when they appear as a function parameter, their template arguments are deduced from other function arguments.

template<class... Args>
std::string format(std::format_string<Args...> fmt, Args&&... args);

auto s = format("{} {}", 1.0, 2);
// Calls format<double, int>. Args are deduced from 1.0, 2
// Due to the use of type_identity_t in format_string, template argument deduction
// does not consider the type of the format string.

examples.code:
#include <format>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <tuple>
#include <cassert>
#include <type_traits>
#include <utility>
struct Custom {
    int value;
};
template <> struct std::formatter<Custom> : std::formatter<int> {
    auto format(const Custom &value, std::format_context &context) const {
        return std::formatter<int>::format(value.value, context);
    }
};
int main() {
    int number = 7;
    auto arguments = std::make_format_args(number);
    std::format_args erased{arguments};
    auto argument = erased.get(0);
    std::visit_format_arg(
        [](auto value) {
            if constexpr (std::is_same_v<decltype(value), int>)
                assert(value == 7);
        },
        argument);
    std::string output;
    std::vformat_to(std::back_inserter(output), "{}", erased);
    assert(output == "7");
    std::format_string<int &> format{"{}"};
    assert(std::format(format, number) == "7");
    auto kind = std::format_kind<std::vector<int>>;
    assert(kind == std::range_format::sequence);
    std::format_parse_context parse{"}"};
    assert(parse.begin() != parse.end());
    parse.advance_to(parse.begin());
    static_assert(std::formattable<int, char>);
    std::vector<int> sequence{1, 2};
    std::map<int, int> mapping{{1, 2}};
    std::set<int> set{1, 2};
    assert(
        !std::format("{} {} {} {}", sequence, mapping, set, std::tuple{1, 2}).empty());
    std::vector<char> letters{'h', 'i'};
    assert(std::format("{:s}", letters) == "hi");
    // Formatting drives basic_format_context and the tuple/range formatter
    // specializations.
    assert(std::format("{}", Custom{9}) == "9");
}
